use vstd::prelude::*;

verus! {

fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> (result: Vec<i8>)
    ensures
        if numbers.len() <= 1 {
            result == numbers
        } else {
            result.len() == 2 * numbers.len() - 1
            && forall |i: usize| (i < numbers.len() ==> result[2*i] == numbers[i])
            && forall |j: usize| (
                (j < result.len() && j % 2 == 1) ==> result[j] == delimiter
            )
        }
{
    let n = numbers.len();

    if n <= 1 {
        // Return unchanged
        result = numbers;
        return result;
    }

    // For n >= 2
    let mut res = Vec::<i8>::new();
    res.reserve(2 * n - 1);

    let mut k: usize = 0;
    while k < n - 1
        invariant
            k < n,
            res.len() == 2 * k,
            forall |i: usize| (i < k ==> res[2*i] == numbers[i]),
            forall |j: usize| (
                (j < res.len() && j % 2 == 1) ==> res[j] == delimiter
            ),
        decreases
            n - 1 - k,
    {
        // push numbers[k]
        res.push(numbers[k]);
        // push delimiter
        res.push(delimiter);
        k = k + 1;
    }
    // push last element of numbers
    res.push(numbers[n - 1]);

    result = res;
    return result;
}

}
